		Peers: peers, Budget: bootstrap.FounderResourceBudget{WholeOCPUs: 4, MemoryInGB: 24, BootVolumeGB: 100},
		LaunchDeadline: now.Add(21 * time.Hour)}
	planPayload, err := trust.EncodePayload(plan)
